package bw.co.starsign.security;

import java.util.List;

import org.springframework.http.HttpMethod;

/**
 * Endpoints that stay reachable without a token. The signing portal endpoints are authenticated by the
 * signing invitation token instead, which the signing services validate on every call.
 * <p>
 * Generated by {@code keycloak/generate_authz.py} from its authorization matrix; do not edit by hand.
 */
public final class PublicEndpoints {

    public record Endpoint(HttpMethod method, String pattern) {
    }

    public static final List<Endpoint> ENDPOINTS = List.of(
            new Endpoint(HttpMethod.GET, "/branding"),
            new Endpoint(HttpMethod.GET, "/branding/assets/*"),
            new Endpoint(HttpMethod.GET, "/branding/organisations/*"),
            new Endpoint(HttpMethod.GET, "/branding/organisations/*/assets/*"),
            new Endpoint(HttpMethod.GET, "/signing/invitations/*"),
            new Endpoint(HttpMethod.GET, "/signing/invitations/*/completed"),
            new Endpoint(HttpMethod.GET, "/signing/invitations/*/document"),
            new Endpoint(HttpMethod.GET, "/signing/invitations/*/pages/*"),
            new Endpoint(HttpMethod.POST, "/notifications/receipts"),
            new Endpoint(HttpMethod.POST, "/organisations"),
            new Endpoint(HttpMethod.POST, "/signing/invitations/*/decline"),
            new Endpoint(HttpMethod.POST, "/signing/invitations/*/fields"),
            new Endpoint(HttpMethod.POST, "/signing/invitations/*/sign"),
            new Endpoint(HttpMethod.POST, "/signing/invitations/*/verify"),
            new Endpoint(HttpMethod.POST, "/signing/invitations/*/verify/confirm"));

    /** Protected endpoints that match a public pattern; register them as authenticated before ENDPOINTS. */
    public static final List<Endpoint> PROTECTED_OVERLAPS = List.of();

    private PublicEndpoints() {
    }
}
